using Microsoft.EntityFrameworkCore;
namespace HomeManager.Api;
public sealed class AppDbContext(DbContextOptions<AppDbContext> options) : DbContext(options) {
 public DbSet<User> Users=>Set<User>(); public DbSet<Home> Homes=>Set<Home>(); public DbSet<HomeMember> HomeMembers=>Set<HomeMember>(); public DbSet<HomeInvitation> HomeInvitations=>Set<HomeInvitation>(); public DbSet<TaskItem> Tasks=>Set<TaskItem>(); public DbSet<TaskChecklistItem> TaskChecklistItems=>Set<TaskChecklistItem>(); public DbSet<CalendarEvent> Events=>Set<CalendarEvent>(); public DbSet<MealPlanEntry> Meals=>Set<MealPlanEntry>(); public DbSet<Recipe> Recipes=>Set<Recipe>(); public DbSet<RecipeIngredient> RecipeIngredients=>Set<RecipeIngredient>(); public DbSet<Product> Products=>Set<Product>(); public DbSet<InventoryMovement> InventoryMovements=>Set<InventoryMovement>(); public DbSet<ShoppingList> ShoppingLists=>Set<ShoppingList>(); public DbSet<ShoppingListItem> ShoppingListItems=>Set<ShoppingListItem>(); public DbSet<HouseholdIssue> HouseholdIssues=>Set<HouseholdIssue>();
 protected override void OnModelCreating(ModelBuilder b){b.Entity<User>().HasIndex(x=>x.Email).IsUnique(); b.Entity<HomeMember>().HasKey(x=>new{x.HomeId,x.UserId}); b.Entity<HomeMember>().HasOne(x=>x.Home).WithMany(x=>x.Members).HasForeignKey(x=>x.HomeId); b.Entity<HomeMember>().HasOne(x=>x.User).WithMany().HasForeignKey(x=>x.UserId); b.Entity<HomeInvitation>().HasIndex(x=>x.Token).IsUnique(); b.Entity<TaskChecklistItem>().HasOne(x=>x.Task).WithMany(x=>x.Checklist).HasForeignKey(x=>x.TaskId).OnDelete(DeleteBehavior.Cascade); b.Entity<TaskChecklistItem>().HasIndex(x=>new{x.TaskId,x.Position}); b.Entity<RecipeIngredient>().HasOne(x=>x.Recipe).WithMany(x=>x.Ingredients).HasForeignKey(x=>x.RecipeId).OnDelete(DeleteBehavior.Cascade); b.Entity<ShoppingListItem>().HasOne(x=>x.ShoppingList).WithMany(x=>x.Items).HasForeignKey(x=>x.ShoppingListId).OnDelete(DeleteBehavior.Cascade); b.Entity<InventoryMovement>().HasIndex(x=>new{x.HomeId,x.IdempotencyKey}).IsUnique(); foreach(var t in new[]{typeof(TaskItem),typeof(CalendarEvent),typeof(MealPlanEntry),typeof(Recipe),typeof(Product),typeof(InventoryMovement),typeof(ShoppingList),typeof(HouseholdIssue)}) b.Entity(t).HasIndex("HomeId"); }
}
public class User{public Guid Id{get;set;}=Guid.NewGuid();public string Name{get;set;}="";public string Email{get;set;}="";public string PasswordHash{get;set;}="";}
public class Home{public Guid Id{get;set;}=Guid.NewGuid();public string Name{get;set;}="";public string TimeZone{get;set;}="Europe/Madrid";public List<HomeMember> Members{get;set;}=[];}
public class HomeMember{public Guid HomeId{get;set;}public Home Home{get;set;}=null!;public Guid UserId{get;set;}public User User{get;set;}=null!;public string Role{get;set;}="Member";}
public class HomeInvitation{public Guid Id{get;set;}=Guid.NewGuid();public Guid HomeId{get;set;}public string Email{get;set;}="";public string Token{get;set;}="";public DateTimeOffset ExpiresAt{get;set;}public DateTimeOffset? AcceptedAt{get;set;}}
public abstract class HomeEntity{public Guid Id{get;set;}=Guid.NewGuid();public Guid HomeId{get;set;}public Guid CreatedById{get;set;}public DateTimeOffset CreatedAt{get;set;}=DateTimeOffset.UtcNow;}
public class TaskItem:HomeEntity{public string Title{get;set;}="";public string? Description{get;set;}public DateTimeOffset? DueAt{get;set;}public string Priority{get;set;}="Normal";public string Status{get;set;}="Pending";public Guid? AssignedUserId{get;set;}public DateTimeOffset? CompletedAt{get;set;}public List<TaskChecklistItem> Checklist{get;set;}=[];}
public class TaskChecklistItem{public Guid Id{get;set;}=Guid.NewGuid();public Guid TaskId{get;set;}public TaskItem Task{get;set;}=null!;public string Title{get;set;}="";public bool IsCompleted{get;set;}public int Position{get;set;}}
public class CalendarEvent:HomeEntity{public string Title{get;set;}="";public DateTimeOffset StartsAt{get;set;}public DateTimeOffset? EndsAt{get;set;}public bool IsPrivate{get;set;}}
public class MealPlanEntry:HomeEntity{public string Title{get;set;}="";public string MealType{get;set;}="Dinner";public DateOnly PlannedFor{get;set;}public Guid? RecipeId{get;set;}}
public class Recipe:HomeEntity{public string Name{get;set;}="";public string? Description{get;set;}public int Servings{get;set;}=2;public int PreparationMinutes{get;set;}public List<RecipeIngredient> Ingredients{get;set;}=[];}
public class RecipeIngredient{public Guid Id{get;set;}=Guid.NewGuid();public Guid RecipeId{get;set;}public Recipe Recipe{get;set;}=null!;public Guid? ProductId{get;set;}public string Name{get;set;}="";public decimal Quantity{get;set;}public string Unit{get;set;}="unidad";}
public class Product:HomeEntity{public string Name{get;set;}="";public decimal Quantity{get;set;}public string Unit{get;set;}="unit";public decimal MinimumQuantity{get;set;}public string? Location{get;set;}}
public class InventoryMovement:HomeEntity{public Guid ProductId{get;set;}public decimal QuantityDelta{get;set;}public decimal ResultingQuantity{get;set;}public string Reason{get;set;}="Adjustment";public string IdempotencyKey{get;set;}="";}
public class ShoppingList:HomeEntity{public string Name{get;set;}="";public List<ShoppingListItem> Items{get;set;}=[];}
public class ShoppingListItem{public Guid Id{get;set;}=Guid.NewGuid();public Guid ShoppingListId{get;set;}public ShoppingList ShoppingList{get;set;}=null!;public Guid? ProductId{get;set;}public string Name{get;set;}="";public decimal Quantity{get;set;}=1;public string Unit{get;set;}="unidad";public bool IsPurchased{get;set;}public bool IsReceived{get;set;}public Guid AddedById{get;set;}public decimal? ActualPrice{get;set;}}
public class HouseholdIssue:HomeEntity{public string Title{get;set;}="";public string? Description{get;set;}public string? Location{get;set;}public string Priority{get;set;}="Normal";public string Status{get;set;}="Pending";public Guid? AssignedUserId{get;set;}public Guid? LinkedTaskId{get;set;}public DateTimeOffset? ResolvedAt{get;set;}}
